-- Wipe dependents, then demo students
DELETE FROM public.daily_quiz_results;
DELETE FROM public.student_subject_progress;
DELETE FROM public.student_roadmap_progress;
DELETE FROM public.student_custom_values;
UPDATE public.app_users SET linked_student_id = NULL WHERE linked_student_id IS NOT NULL;
UPDATE public.profiles SET linked_student_id = NULL WHERE linked_student_id IS NOT NULL;
UPDATE public.pending_invites SET linked_student_id = NULL WHERE linked_student_id IS NOT NULL;
UPDATE public.students SET parent_user_id = NULL WHERE parent_user_id IS NOT NULL;
DELETE FROM public.students;


-- Create student_bagrut_data table (admin-only RLS)
CREATE TABLE public.student_bagrut_data (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id uuid NOT NULL UNIQUE REFERENCES public.students(id) ON DELETE CASCADE,
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.student_bagrut_data TO authenticated;
GRANT ALL ON public.student_bagrut_data TO service_role;
ALTER TABLE public.student_bagrut_data ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins can select bagrut data" ON public.student_bagrut_data
  FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can insert bagrut data" ON public.student_bagrut_data
  FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update bagrut data" ON public.student_bagrut_data
  FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete bagrut data" ON public.student_bagrut_data
  FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TRIGGER update_student_bagrut_data_updated_at
  BEFORE UPDATE ON public.student_bagrut_data
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

